2	 * BDD step definitions for feature-537.feature
3	 * hashComputer deep module — framework content hash
4	 *
5	 * Steps NOT defined here (already defined elsewhere):
6	 *   - Given 'the ADW codebase is checked out'      → ensureCronOnEveryEventSteps.ts
7	 *   - Then  'the ADW TypeScript type-check passes'  → feature-504.steps.ts
8	 *
9	 * Fixture approach: each scenario that needs a fixture framework creates a
10	 * temporary directory. Given steps write files into it; When steps invoke
11	 * computeFrameworkHash and append the result to recordedHashes. After hook
12	 * cleans up the temp dirs.
13	 */
14	
15	import { Before, After, Given, When, Then } from '@cucumber/cucumber';
16	import type { DataTable } from '@cucumber/cucumber';
17	import assert from 'assert';
18	import * as fs from 'fs';
19	import * as os from 'os';
20	import * as path from 'path';
21	import { computeFrameworkHash } from '../../../adws/core/hashComputer.ts';
22	
23	// ---------------------------------------------------------------------------
24	// Per-scenario mutable state
25	// ---------------------------------------------------------------------------
26	
27	interface Ctx537 {
28	  fixtureRoot: string | null;
29	  secondFixtureRoot: string | null;
30	  recordedHashes: string[];
31	  lastError: Error | null;
32	}
33	
34	const ctx: Ctx537 = {
35	  fixtureRoot: null,
36	  secondFixtureRoot: null,
37	  recordedHashes: [],
38	  lastError: null,
39	};
40	
41	// ---------------------------------------------------------------------------
42	// Helpers
