51	  const dir = path.join(root, '.claude', 'commands');
52	  fs.mkdirSync(dir, { recursive: true });
53	  fs.writeFileSync(path.join(dir, 'adw_init.md'), makeAdwInitContent(hashInputs), 'utf-8');
54	}
