58	  fs.mkdirSync(path.dirname(absPath), { recursive: true });
59	  fs.writeFileSync(absPath, content, 'utf-8');
60	}
61	
62	function cleanup(tmpDir: string | null): void {
63	  if (tmpDir) {
64	    try {
65	      fs.rmSync(tmpDir, { recursive: true, force: true });
66	    } catch {
67	      // best-effort
68	    }
69	  }
70	}
71	
72	// ---------------------------------------------------------------------------
73	// Before / After hooks
74	// ---------------------------------------------------------------------------
75	
76	Before({ tags: '@adw-537' }, function () {
77	  ctx.fixtureRoot = null;
78	  ctx.secondFixtureRoot = null;
79	  ctx.recordedHashes = [];
80	  ctx.lastError = null;
81	});
