83	After({ tags: '@adw-537' }, function () {
84	  cleanup(ctx.fixtureRoot);
85	  cleanup(ctx.secondFixtureRoot);
86	  ctx.fixtureRoot = null;
87	  ctx.secondFixtureRoot = null;
88	});
