90	// ---------------------------------------------------------------------------
91	// Given — primary fixture setup
92	// ---------------------------------------------------------------------------
93	
94	Given(
95	  'a fixture framework whose adw_init spec declares hash inputs:',
96	  function (dataTable: DataTable) {
97	    const hashInputs = dataTable.hashes().map((row: Record<string, string>) => row['path']);
98	    ctx.fixtureRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'adw-537-fixture-'));
