106	  fs.mkdirSync(dir, { recursive: true });
107	  fs.writeFileSync(
108	    path.join(dir, 'adw_init.md'),
109	    '---\ntarget: false\n---\n# no hashInputs\n',
110	    'utf-8',
111	  );
112	});
113	
114	Given(
115	  'the fixture input file {string} contains {string}',
116	  function (filePath: string, content: string) {
117	    assert.ok(ctx.fixtureRoot, 'fixture root must be set before writing input files');
118	    writeFixtureFile(ctx.fixtureRoot, filePath, content);
119	  },
120	);
