122	// ---------------------------------------------------------------------------
123	// Given — second fixture setup
124	// ---------------------------------------------------------------------------
125	
126	Given(
127	  'a second fixture framework whose adw_init spec declares hash inputs:',
128	  function (dataTable: DataTable) {
129	    const hashInputs = dataTable.hashes().map((row: Record<string, string>) => row['path']);
130	    ctx.secondFixtureRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'adw-537-fixture2-'));
131	    writeAdwInit(ctx.secondFixtureRoot, hashInputs);
132	  },
133	);
134	
135	Given(
136	  'the fixture input file {string} in the second fixture framework contains {string}',
137	  function (filePath: string, content: string) {
138	    assert.ok(ctx.secondFixtureRoot, 'second fixture root must be set');
139	    writeFixtureFile(ctx.secondFixtureRoot, filePath, content);
140	  },
141	);
142	
143	// ---------------------------------------------------------------------------
144	// When — hash computation
145	// ---------------------------------------------------------------------------
146	
147	When('the framework content hash is computed for the fixture framework', function () {
148	  assert.ok(ctx.fixtureRoot, 'fixture root must be set');
149	  const hash = computeFrameworkHash(ctx.fixtureRoot);
150	  ctx.recordedHashes.push(hash);
151	});
152	
153	When(
154	  'the framework content hash computation is attempted for the fixture framework',
155	  function () {
156	    assert.ok(ctx.fixtureRoot, 'fixture root must be set');
157	    try {
158	      const hash = computeFrameworkHash(ctx.fixtureRoot);
159	      ctx.recordedHashes.push(hash);
160	      ctx.lastError = null;
161	    } catch (err) {
162	      ctx.lastError = err instanceof Error ? err : new Error(String(err));
163	    }
164	  },
165	);
166	
167	When(
168	  'the hash inputs in the fixture adw_init spec are reordered to:',
169	  function (dataTable: DataTable) {
170	    assert.ok(ctx.fixtureRoot, 'fixture root must be set');
171	    const newOrder = dataTable.hashes().map((row: Record<string, string>) => row['path']);
172	    writeAdwInit(ctx.fixtureRoot, newOrder);
173	  },
174	);
175	
176	When(
177	  'the fixture input file {string} is modified by a single byte',
178	  function (filePath: string) {
179	    assert.ok(ctx.fixtureRoot, 'fixture root must be set');
180	    const absPath = path.join(ctx.fixtureRoot, filePath);
181	    const existing = fs.readFileSync(absPath);
182	    const modified = Buffer.from(existing);
183	    modified[0] = modified[0] ^ 0xff;
184	    fs.writeFileSync(absPath, modified);
185	  },
186	);
187	
188	When('the framework content hash is computed for the second fixture framework', function () {
189	  assert.ok(ctx.secondFixtureRoot, 'second fixture root must be set');
190	  const hash = computeFrameworkHash(ctx.secondFixtureRoot);
191	  ctx.recordedHashes.push(hash);
192	});
193	
194	When('the framework content hash is computed for the ADW framework under test', function () {
195	  const hash = computeFrameworkHash(process.cwd());
196	  ctx.recordedHashes.push(hash);
197	});
198	
199	// ---------------------------------------------------------------------------
200	// Then — assertions
201	// ---------------------------------------------------------------------------
202	
203	Then(
204	  'the most recent computed hash is a 64-character lowercase hexadecimal SHA256 digest',
205	  function () {
206	    assert.ok(ctx.recordedHashes.length > 0, 'Expected at least one recorded hash');
207	    const last = ctx.recordedHashes[ctx.recordedHashes.length - 1];
208	    assert.match(
209	      last,
210	      /^[0-9a-f]{64}$/,
211	      `Expected a 64-char lowercase hex SHA256 digest, got: "${last}"`,
212	    );
213	  },
214	);
215	
216	Then('the recorded hashes are all identical', function () {
217	  assert.ok(ctx.recordedHashes.length >= 2, 'Expected at least two recorded hashes');
218	  const first = ctx.recordedHashes[0];
219	  for (const h of ctx.recordedHashes) {
220	    assert.strictEqual(h, first, `Expected all hashes to be identical; got "${h}" vs "${first}"`);
221	  }
222	});
223	
224	Then('the recorded hashes are all different', function () {
225	  assert.ok(ctx.recordedHashes.length >= 2, 'Expected at least two recorded hashes');
226	  const unique = new Set(ctx.recordedHashes);
227	  assert.strictEqual(
228	    unique.size,
229	    ctx.recordedHashes.length,
230	    `Expected all hashes to be different but found duplicates: ${JSON.stringify(ctx.recordedHashes)}`,
231	  );
232	});
233	
234	Then(
235	  'the hash computation fails with an error reporting the absent hash inputs declaration',
236	  function () {
237	    assert.ok(ctx.lastError, 'Expected an error to have been thrown');
238	    assert.ok(
239	      ctx.lastError.message.includes('hashInputs'),
240	      `Expected error message to mention "hashInputs", got: "${ctx.lastError.message}"`,
241	    );
242	  },
243	);
244	
245	Then(
246	  'the hash computation fails with an error that names the missing input file {string}',
247	  function (missingFile: string) {
248	    assert.ok(ctx.lastError, 'Expected an error to have been thrown');
249	    assert.ok(
250	      ctx.lastError.message.includes(missingFile),
251	      `Expected error message to mention "${missingFile}", got: "${ctx.lastError.message}"`,
252	    );
253	  },
254	);
